          name: "Lumen: Photo Journal",
          plan: "Lumen Pro (Monthly)",
          renews: "Renews Aug 20",
          price: 14.99,
        },
      ],
    },
    render: (v) => {
      const subtotal = v.items.reduce((sum, item) => sum + item.price, 0);
      const total = v.taxes.reduce((sum, tax) => sum + tax.amount, subtotal);
      return (
        <Email
          width={640}
