                    src={item.icon}
                    alt={item.name}
                    style={{ width: 64, borderRadius: token("radii.md"), border: { width: 1, style: "solid", color: token("colors.border") } }}
                  />
                  <Column style={{ gap: 2 }}>
                    <Text field={`items[${i}].name`} style={{ fontWeight: 700 }}>{item.name}</Text>
