      const inPerson = v.attendance !== "online";
      const online = v.attendance !== "in person";
      const place = inPerson ? [v.venue, ...v.address].filter(Boolean).join(", ") : "";
      const where = [place, online ? (place ? "and online" : "Online") : ""].filter(Boolean).join(" ");
