const dates = (start: string, end?: string) => {
  if (!end || end === start) return start;
  const [startMonth] = start.split(" ");
  const [endMonth, endDay] = end.split(" ");
  return startMonth === endMonth ? `${start}–${endDay}` : `${start} – ${end}`;
};

