              <Text field="customer">
                {overdue
                  ? `Hello ${v.customer}, this invoice from ${brand.name} is past its due date.${v.attached ? " The PDF is attached." : ""}`
                  : `Hello ${v.customer}, here's your invoice from ${brand.name}.${v.attached ? " The PDF is attached." : ""}`}
