import { lint } from "@hyper-elements/lint";
import { Button, Column, Divider, Email, Heading, Image, LineBreak, Link, List, ListItem, Row, Span, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { field, template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show: a marketing email shows it. */
  address?: string;
  /**
   * The brand's site, the hosts its links may go to (`acme.example`, or `*.acme.example`), and the pages a template
   * links to that belong to the brand, not to a send: where a reader unsubscribes in one step, chooses which emails
   * they get, and gets help. `payments` are other hosts a payment link may go to (a payment processor's).
   */
  links: {
    site: string;
    domains: readonly string[];
    unsubscribe: string;
    preferences: string;
    help: string;
    payments?: readonly string[];
  };
  /** The currency amounts are in, as an ISO 4217 code ("USD"), written in the brand's language. */
  currency: string;
  /** Who the brand is in law, for invoices and receipts: its registered name, and its tax or VAT number. */
  legal?: { entity: string; taxId?: string };
  /** How a reader reaches support, where a template shows it. */
  support?: { phone?: string; hours?: string };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Quarry",
  theme: defineTheme({
    colors: {
      background: "#0e0f10",
      foreground: "#eceae4",
      primary: "#d4f25a",
      primaryForeground: "#0e0f10",
      border: "#2b2d30",
      muted: "#a3a199",
      surface: "#17191b",
      accent: "#c2e040",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'JetBrains Mono', Menlo, Consolas, monospace" },
    fontSizes: { body: 15, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 12, lg: 20, xl: 32 },
    radii: { sm: 4, md: 8 },
    elements: {
      Heading: {
        fontWeight: 500,
        by: {
          level: {
            1: { fontSize: 28, lineHeight: 1.15 },
            2: { fontSize: 21, lineHeight: 1.25 },
            3: { fontSize: 17, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/quarry/logo.png", width: 480, height: 120, alt: "Quarry" },
  address: "88 Kiln Road, Austin",
  links: {
    site: "https://quarry.example",
    domains: ["quarry.example", "*.quarry.example"],
    unsubscribe: "https://quarry.example/unsubscribe",
    preferences: "https://quarry.example/account/emails",
    help: "https://quarry.example/help",
  },
  currency: "USD",
  legal: { entity: "Quarry Goods, LLC", taxId: "EIN 34-5678901" },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "JetBrains Mono", src: "https://hyperelements.dev/generated/gallery/assets/fonts/JetBrainsMono-500.ttf", weight: 500, style: "normal" },
  ],
};
// brand: end

const fields = {
  // The header: the subject and preview text the inbox shows, and the issue beside the logo.
  subject: prop.text({ label: "Subject", required: true, pattern: "^[\\s\\S]{10,70}$", guidance: "10 to 70 characters, in sentence case" }),
  preview: prop.text({ label: "Preview text", required: true, pattern: "^[\\s\\S]{30,120}$", guidance: "What the inbox shows after the subject: 30 to 120 characters" }),
  issue: prop.text({
    label: "Issue",
    required: true,
    // What fits beside the logo on one line, with no year, so it reads the same any time.
    pattern: "^(?![\\s\\S]*\\b(19|20)\\d{2}\\b)[\\s\\S]{3,32}$",
    guidance: "Its number and date, with no year: No. 14 · March 5",
  }),
  // The body: the issue's own sections.
  body: field.slot({
    label: "Body",
    required: true,
    allow: [Column, Row, Heading, Text, Span, Link, LineBreak, Button, Image, Divider, List, ListItem],
    styles: "theme",
    count: { Button: { max: 3 }, Image: { max: 6 } },
    guidance: "Two to five short sections, each a heading and a few sentences, a button or a link to read more. Images have alt text, or alt=\"\" for a decorative one. Friendly and plain: sentence case, no exclamation marks, no emoji.",
  }),
};

export function newsletter(brand: Brand) {
  const small = { fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "center" } as const;
  return template({
    id: "emails.Newsletter",
    version: "1.0.0",
    label: "Newsletter",
    description: "A regular issue: a locked masthead and footer, with the issue, an unsubscribe link and the company's address, around a body of sections the issue writes",
    root: "Email",
    fields,
    rules: {
      plugins: { lint: lint({ kind: "marketing" }) },
      require: { lint: ["unsubscribe", "preview-text", "link-text", "alt-text", "contrast", "text-size", "lang"], core: ["layout/overflow"] },
      // A {{…}} tag can't carry a link past the domain rule.
      links: { domains: [...brand.links.domains], tags: "deny" },
    },
    example: {
      subject: "What's new this month",
      preview: "Faster exports, and a date for the open house in the studio",
      issue: "No. 1 · January 9",
      body: (
        <Column style={{ gap: token("spacing.md") }}>
          <Heading level={1}>Exports that finish in seconds</Heading>
          <Text>Big projects that took minutes now take seconds, with nothing to change in your settings.</Text>
          <Button href={`${brand.links.site}/blog/faster-exports`}>Read about faster exports</Button>
        </Column>
      ),
    },
    render: (v) => (
      <Email
        width={600}
        title={v.subject}
        previewText={v.preview}
        lang={brand.lang ?? "en"}
        dir={brand.dir}
        theme={brand.theme}
        fonts={brand.fonts}
        style={{ backgroundColor: token("colors.surface"), fontSize: token("fontSizes.body"), lineHeight: token("lineHeights.body") }}
      >
        <Column style={{ padding: [token("spacing.lg"), token("spacing.md")], gap: token("spacing.lg") }}>
          <Row stackOnMobile={false} style={{ alignItems: "center", gap: token("spacing.md"), padding: [0, token("spacing.sm")] }}>
            <Column>
              <Image src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }} alt={brand.logo.alt} style={{ width: 140 }} />
            </Column>
            <Column>
              <Text field="issue" style={{ ...small, textAlign: "right" }}>{v.issue}</Text>
            </Column>
          </Row>
          <Column
            field="body"
            style={{
              backgroundColor: token("colors.background"),
              borderRadius: token("radii.md"),
              border: { width: 1, style: "solid", color: token("colors.border") },
              padding: token("spacing.xl"),
            }}
          >
            {v.body}
          </Column>
          <Column style={{ padding: [0, token("spacing.sm")], gap: token("spacing.xs") }}>
            <Text style={small}>You're getting {brand.name}'s newsletter because you signed up for it.</Text>
            <Text style={small}>{brand.address ? `${brand.name}, ${brand.address}` : brand.name}</Text>
            <Text style={small}>
              <Link href={brand.links.unsubscribe}>Unsubscribe from these emails</Link>
              {" · "}
              <Link href={brand.links.preferences}>Choose which emails you get</Link>
            </Text>
          </Column>
        </Column>
      </Email>
    ),
  });
}

export default newsletter(brand);

