                  </Column>
                  <Column>
                    <Text style={{ ...small, textAlign: "right" }}>Placed on</Text>
                    <Text field="placedOn" style={{ fontWeight: 700, textAlign: "right" }}>{v.placedOn}</Text>
                  </Column>
                </Row>
