    // Never a whole card or account number: no more than four digits in a row.
    pattern: "^(?![\\s\\S]*(?:\\d[\\s-]?){5})[\\s\\S]{3,40}$",
    guidance: "The card or account, by its last four digits only: Visa ending 4242",
