    },
    { label: "Plan", required: true },
  ),
  email: prop.text({ label: "Reader's email address", required: true, pattern: "^(?=[\\s\\S]{6,254}$)[^@\\s]+@[^@\\s]+\\.[^@\\s]+$" }),
};

