import { defineTheme } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
export type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

export type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show: a marketing email shows it. */
  address?: string;
  /**
   * The brand's site, the hosts its links may go to (`acme.example`, or `*.acme.example`), and the pages a template
   * links to that belong to the brand, not to a send: where a reader unsubscribes in one step, chooses which emails
   * they get, and gets help. `payments` are other hosts a payment link may go to (a payment processor's).
   */
  links: {
    site: string;
    domains: readonly string[];
    unsubscribe: string;
    preferences: string;
    help: string;
    payments?: readonly string[];
  };
  /** The currency amounts are in, as an ISO 4217 code ("USD"), written in the brand's language. */
  currency: string;
  /** Who the brand is in law, for invoices and receipts: its registered name, and its tax or VAT number. */
  legal?: { entity: string; taxId?: string };
  /** How a reader reaches support, where a template shows it. */
  support?: { phone?: string; hours?: string };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

export const brand: Brand = {
  name: "Keel",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#0b0d0c",
      primary: "#0f5c45",
      primaryForeground: "#ffffff",
      border: "#e2e4e2",
      muted: "#5a5f5c",
      surface: "#f3f4f2",
      accent: "#9fd8c2",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'JetBrains Mono', Menlo, Consolas, monospace" },
    fontSizes: { body: 15, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 12, lg: 20, xl: 32 },
    radii: { sm: 4, md: 10 },
    elements: {
      Heading: {
        fontWeight: 500,
        by: {
          level: {
            1: { fontSize: 28, lineHeight: 1.15 },
            2: { fontSize: 21, lineHeight: 1.25 },
            3: { fontSize: 17, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/keel/logo.png", width: 480, height: 120, alt: "Keel" },
  address: "200 Harbor Street, Boston",
  links: {
    site: "https://keel.example",
    domains: ["keel.example", "*.keel.example"],
    unsubscribe: "https://keel.example/unsubscribe",
    preferences: "https://keel.example/account/emails",
    help: "https://keel.example/help",
  },
  currency: "USD",
  legal: { entity: "Keel Labs, LLC", taxId: "EIN 98-7654321" },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
