                <Link href={`${site}/legal/privacy`} style={{ ...link, color: token("colors.muted") }}>Privacy Policy</Link> ·{" "}
                <Link href={brand.links.help} style={{ ...link, color: token("colors.muted") }}>Contact Us</Link>
              </Text>
