import { Button, Column, Email, Heading, Image, Link, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show: a marketing email shows it. */
  address?: string;
  /**
   * The brand's site, the hosts its links may go to (`acme.example`, or `*.acme.example`), and the pages a template
   * links to that belong to the brand, not to a send: where a reader unsubscribes in one step, chooses which emails
   * they get, and gets help. `payments` are other hosts a payment link may go to (a payment processor's).
   */
  links: {
    site: string;
    domains: readonly string[];
    unsubscribe: string;
    preferences: string;
    help: string;
    payments?: readonly string[];
  };
  /** The currency amounts are in, as an ISO 4217 code ("USD"), written in the brand's language. */
  currency: string;
  /** Who the brand is in law, for invoices and receipts: its registered name, and its tax or VAT number. */
  legal?: { entity: string; taxId?: string };
  /** How a reader reaches support, where a template shows it. */
  support?: { phone?: string; hours?: string };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Slow Signals",
  theme: defineTheme({
    colors: {
      background: "#1b1712",
      foreground: "#f1e8d6",
      primary: "#f2b544",
      primaryForeground: "#1b1712",
      border: "#3a332a",
      muted: "#b3a891",
      surface: "#241f18",
      accent: "#f2b544",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'Source Serif 4', Georgia, 'Times New Roman', serif" },
    fontSizes: { body: 17, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 6, sm: 12, md: 20, lg: 32, xl: 56 },
    radii: { sm: 8, md: 16 },
    elements: {
      Heading: {
        fontWeight: 600,
        by: {
          level: {
            1: { fontSize: 34, lineHeight: 1.15 },
            2: { fontSize: 25, lineHeight: 1.25 },
            3: { fontSize: 20, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/slow-signals/logo.png", width: 480, height: 120, alt: "Slow Signals" },
  address: "PO Box 1170, Taos",
  links: {
    site: "https://slowsignals.example",
    domains: ["slowsignals.example", "*.slowsignals.example"],
    unsubscribe: "https://slowsignals.example/unsubscribe",
    preferences: "https://slowsignals.example/account/emails",
    help: "https://slowsignals.example/help",
  },
  currency: "USD",
  legal: { entity: "Slow Signals Radio, Inc.", taxId: "EIN 67-8901234" },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/gallery/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "Source Serif 4", src: "https://hyperelements.dev/generated/gallery/assets/fonts/SourceSerif4-600.ttf", weight: 600, style: "normal" },
  ],
};
// brand: end

const fields = {
  email: prop.text({
    label: "Email address",
    required: true,
    // An address, as long as an address can be: it wraps in its box.
    maxLength: 254,
    pattern: "^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$",
    guidance: "The address the account was made with, up to 254 characters",
  }),
  verifyLink: prop.link({ label: "Confirmation link", required: true, guidance: "The one-time link that confirms the address" }),
  // Both or neither: shown under the button only when it's given.
  expiry: prop.object(
    {
      expires: prop.number({ label: "Expires in", required: true, min: 1, max: 72, integer: true, guidance: "How long the link works, in the unit below: 24" }),
      unit: prop.choice(["minutes", "hours", "days"], { label: "Unit", required: true, guidance: "The unit of how long the link works: hours" }),
    },
    { label: "Expiry" },
  ),
};

/** How long something works, as a reader says it: "10 minutes", "1 hour". */
const duration = (n: number, unit: "minutes" | "hours" | "days") => `${n} ${n === 1 ? unit.slice(0, -1) : unit}`;
/** A link's address, written out for a reader to paste. */
const written = (link: string | { href: string }) => (typeof link === "string" ? link : link.href);

export function verifyEmail(brand: Brand) {
  const small = { fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "center" } as const;
  return template({
    id: "emails.VerifyEmail",
    version: "1.0.0",
    label: "Verify email",
    description: "One step before the account is ready: confirm the email address it was made with",
    root: "Email",
