                        </Column>
                      </Row>
                    ))}
                  </Column>
                )}
                {v.speakers.length > 0 && (
                  <Column style={{ gap: token("spacing.md") }}>
                    <Heading level={2}>Speakers</Heading>
                    {v.speakers.map((speaker, i) => (
                      <Row
