        amount: prop.number({ label: "Amount", required: true, min: -100000, max: 100000, guidance: "In the brand's currency, as a number: 444, or -106 for a discount" }),
      },
      { label: "Price line" },
    ),
    { label: "Price breakdown", required: true, min: 1, max: 10 },
