          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/gallery/assets/brands/slow-signals/logo.png", width: 480, height: 120, alt: "Slow Signals" },
  address: "PO Box 1170, Taos",
  links: {
