              ) : (
                <Row stackOnMobile={false} style={{ alignItems: "center", gap: token("spacing.md") }}>
                  <Column>
                    <Image src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }} alt={brand.logo.alt} style={{ width: 110 }} />
                  </Column>
                  <Column>
