  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Casa Albero",
  theme: defineTheme({
    colors: {
      background: "#fbf7f0",
      foreground: "#2b2420",
      primary: "#9c3f24",
      primaryForeground: "#ffffff",
      border: "#e4dacb",
      muted: "#665c54",
      surface: "#f2eadd",
      accent: "#d9b48a",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'Source Serif 4', Georgia, 'Times New Roman', serif" },
    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 6, sm: 12, md: 20, lg: 32, xl: 56 },
    radii: { sm: 12, md: 24 },
    elements: {
      Heading: {
        fontWeight: 600,
        by: {
          level: {
            1: { fontSize: 36, lineHeight: 1.15 },
            2: { fontSize: 26, lineHeight: 1.25 },
