      },
      { label: item },
    ),
    { label: list, min: 0, max: 3 },
  );

const fields = {
  number: prop.text({ label: "Receipt number", required: true, pattern: "^[A-Za-z0-9][A-Za-z0-9-]{2,11}$", guidance: "Letters, digits and dashes: R-20418" }),
