    <Circle cx={12} cy={12} r={12} style={{ fill: token("colors.primary") }} />
    <Path d="M6.5 12.5 L10.5 16.5 L17.5 8.5" style={{ fill: "transparent", stroke: token("colors.primaryForeground"), strokeWidth: 2.6 }} />
